package thaumcraft.warp;
import java.util.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.effect.*;
import net.minecraft.world.phys.*;
import net.minecraft.sounds.*;
import net.minecraftforge.event.TickEvent;
import thaumcraft.persistence.PlayerWarpStore;
import thaumcraft.research.*;
import thaumcraft.taint.*;
public final class WarpEngine {
 private WarpEngine(){}
 public static int gear(Player p){int n=weight(p.getMainHandItem());for(var s:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET))n+=weight(p.getItemBySlot(s));for(var accessory:thaumcraft.equipment.AccessorySlots.equipped(p)){n+=weight(accessory);if(thaumcraft.equipment.EquipmentContent.name(accessory).equals("charm_voidseer")&&p instanceof ServerPlayer real)n+=PlayerWarpStore.read(real).result().map(w->Math.min(100,w.permanent())/20).orElse(0);}return n;}
 private static int weight(net.minecraft.world.item.ItemStack s){String n=thaumcraft.equipment.EquipmentContent.name(s);return thaumcraft.infusion.InfusionEnchantments.warp(s)+(n.equals("primal_crusher")||n.equals("crimson_blade")?2:n.startsWith("crimson_robe_")||n.equals("crimson_boots")?1:n.startsWith("void_robe_")?3:n.startsWith("void_")?1:0);}
 public static boolean check(ServerPlayer p,int roll,int sample){if(!p.isAlive()||p.isSpectator()||p.isCreative()||thaumcraft.config.ThaumcraftConfig.wussMode.get()||p.hasEffect(TaintContent.WARD.getHolder().orElseThrow()))return false;var saved=PlayerWarpStore.read(p).result();if(saved.isEmpty())return false;var w=saved.get();var d=WarpRules.decide(w,gear(p),roll,sample);var next=new PlayerWarpStore.State(w.version(),w.permanent(),w.normal(),d.temporary(),d.counter());if(PlayerWarpStore.write(p,next).result().isEmpty())return false;if(!d.triggered())return false;
  event(p,Math.max(0,d.severity()-(thaumcraft.equipment.FortressMasks.worn(p)==0?2+p.getRandom().nextInt(4):0)),d.power());int actual=w.permanent()+w.normal();if(actual>10)ResearchService.flag(p,"!BATHSALTS");if(actual>25)ResearchService.flag(p,"ELDRITCHMINOR");if(actual>50)ResearchService.flag(p,"ELDRITCHMAJOR");return true;
 }
 private static void effect(ServerPlayer p,net.minecraftforge.registries.RegistryObject<MobEffect> type,int ticks,int amp){p.addEffect(new MobEffectInstance(type.getHolder().orElseThrow(),ticks,amp,true,true));}
 public static void event(ServerPlayer p,int severity,int power){if(severity<0||severity>200||power<1||power>100)throw new IllegalArgumentException("Invalid warp event");if(thaumcraft.config.ThaumcraftConfig.wussMode.get()||p.hasEffect(TaintContent.WARD.getHolder().orElseThrow()))return;int band=WarpRules.band(severity),amp=Math.min(3,power/15),text=0;
  switch(band){case 1->WarpFeedback.send(p,1);case 2->WarpFeedback.send(p,2);case 3->text=11;case 4->{effect(p,TaintContent.EXHAUST,5000,amp);text=1;}case 5->{effect(p,WarpContent.THAUMARHIA,Math.min(32000,10*power),0);text=15;}case 6,20->{effect(p,WarpContent.HUNGER,band==6?5000:6000,amp);text=2;}case 7->text=12;case 8,17,23->{p.addEffect(new MobEffectInstance(MobEffects.DARKNESS,Math.min(6000,power*10)));WarpCreatures.mist(p,band==8?1:power/(band==17?30:15));text=6;}case 9->{effect(p,WarpContent.BLURRED,Math.min(32000,10*power),0);p.addEffect(new MobEffectInstance(MobEffects.NAUSEA,Math.min(32000,10*power)));}case 10->{effect(p,WarpContent.SUN,5000,amp);text=5;}case 11->{p.addEffect(new MobEffectInstance(MobEffects.MINING_FATIGUE,1200,amp));text=9;}case 12->{effect(p,TaintContent.INFECTIOUS,6000,amp);text=1;}case 13->{p.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION,Math.min(40*power,6000)));text=10;}case 14->{effect(p,WarpContent.GAZE,6000,amp);text=4;}case 15,22->{WarpCreatures.spiders(p,power,band==22);text=7;}case 16->text=13;case 18->p.addEffect(new MobEffectInstance(MobEffects.BLINDNESS,Math.min(32000,5*power)));case 19->{var w=PlayerWarpStore.read(p).result();if(w.isPresent())PlayerWarpStore.write(p,WarpRules.add(w.get(),0,-1,0));text=14;}case 21->{if(WarpCreatures.portal(p))text=16;}default->{}}
  if(text>0)p.sendOverlayMessage(net.minecraft.network.chat.Component.translatable("warp.text."+text).withStyle(net.minecraft.ChatFormatting.DARK_PURPLE,net.minecraft.ChatFormatting.ITALIC));
 }
 public static void gaze(ServerPlayer p,int amp){if(p.isSpectator())return;int range=Math.min(24,8+amp*3);var start=p.getEyePosition();var look=p.getViewVector(1);for(var e:p.level().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(range),e->e!=p&&e.isAlive()&&!e.isSpectator())){if(e.hasEffect(MobEffects.WITHER)||thaumcraft.thaumaturgy.SpellEngine.protectedTarget(p,e))continue;var end=e.getEyePosition();var delta=end.subtract(start);if(delta.lengthSqr()>range*range||look.dot(delta.normalize())<.75||!thaumcraft.thaumaturgy.SpellEngine.loadedLine(p.level(),start,end)||p.level().clip(new net.minecraft.world.level.ClipContext(start,end,net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,p)).getType()!=HitResult.Type.MISS)continue;e.addEffect(new MobEffectInstance(MobEffects.WITHER,80));if(e instanceof Mob m)m.setTarget(p);}}
 public static void register(){WarpFeedback.register();TickEvent.PlayerTickEvent.Post.BUS.addListener(e->{if(!(e.player() instanceof ServerPlayer p)||!p.isAlive())return;long now=p.level().getGameTime(),due=p.getPersistentData().getLongOr("tc_warp_next",0);if(due==0||due>now+2000){p.getPersistentData().putLong("tc_warp_next",now+2000);return;}if(now>=due){p.getPersistentData().putLong("tc_warp_next",now+2000);var w=PlayerWarpStore.read(p).result();if(w.isPresent()){int roll=p.getRandom().nextInt(100);int power=WarpRules.decide(w.get(),gear(p),roll,0).power();check(p,roll,p.getRandom().nextInt(Math.max(1,power)));}}});
  net.minecraftforge.event.entity.living.LivingEntityUseItemEvent.Finish.BUS.addListener(e->{if(e.getEntity() instanceof ServerPlayer p&&(e.getItem().is(net.minecraft.world.item.Items.ROTTEN_FLESH)||e.getItem().is(thaumcraft.infusion.CuriosityContent.BRAIN.get())))p.removeEffect(WarpContent.HUNGER.getHolder().orElseThrow());});
 }
}
